INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6816206, 1024989, 62249, '<td valign="top">The stem of the goblet and the reflection are interesting. The upper part of the goblet, not so much.</td>', 'The stem of the goblet and the reflection are interesting. The upper part of the goblet, not so much.', '2012-07-12 13:04:34.000000', NULL, 1),
